                <div class="box">
                    <div class="data-row"><span class="label">ACOMP. MÉDICO / PSI</span><span class="value">${t.saudeAcompanhamentos.acompanhamentoMedico||"-"} / ${t.saudeAcompanhamentos.acompanhamentoPsi||"-"}</span></div>
                    <div class="data-row"><span class="label">MEDICAÇÃO CONTÍNUA</span><span class="value">${t.saudeAcompanhamentos.medicacaoContinua||"-"} ${t.saudeAcompanhamentos.qualMedicacao?`(${t.saudeAcompanhamentos.qualMedicacao})`:""}</span></div>
                    <div class="data-row"><span class="label">CONSELHO TUTELAR / SERVIÇOS</span><span class="value">${t.saudeAcompanhamentos.conselhoTutelar||"-"} | ${L(t.saudeAcompanhamentos.servicosAtendimento)} ${t.saudeAcompanhamentos.outrosServicos?` - ${t.saudeAcompanhamentos.outrosServicos}`:""}</span></div>
                </div>

